"""Offline audit; semantic grading remains an explicitly separate manual step."""

import argparse
import hashlib
import json
from collections import Counter
from pathlib import Path
from typing import Any

from analyze_pilot import summarize_trace
from caliburn.adapters.openai_models import model_profile
from caliburn.adapters.response_serialization import restore_response
from main_support import window_fingerprint
from openai.types.responses.compacted_response import CompactedResponse
from preparation import ARMS


def audit_chains(rows: list[dict[str, Any]]) -> dict[str, Any]:
    prefixes: dict[tuple[str, str], list[Any]] = {}
    pending: dict[tuple[str, str], list[str]] = {}
    owners: dict[tuple[str, str], tuple[str, str]] = {}
    awaiting_adoption: set[tuple[str, str]] = set()
    key = None
    issues = []
    continuations = 0
    tool_results = 0
    adoptions = 0

    def check(items: list[Any], owner: tuple[str, str], index: int) -> None:
        nonlocal continuations, tool_results
        if owner not in prefixes:
            return
        continuations += 1
        prefix = prefixes[owner]
        if items[: len(prefix)] != prefix:
            issues.append({"row": index, "kind": "native_prefix_changed"})
        results = [
            item["call_id"]
            for item in items[len(prefix) :]
            if item.get("type") == "function_call_output"
        ]
        if results != pending.get(owner, []):
            issues.append({"row": index, "kind": "tool_call_pairing_changed"})
        tool_results += len(pending.get(owner, []))
        pending[owner] = []

    for index, row in enumerate(rows, 1):
        path = row.get("path")
        if row.get("event") not in {"request", "response"}:
            continue
        payload = row["payload"]
        arm = row["arm"]
        if row["event"] == "request":
            if path == "/v1/responses/input_tokens":
                owner = (arm, hashlib.sha256(payload["instructions"].encode()).hexdigest())
                owners[arm, window_fingerprint(payload)] = owner
            elif path == "/v1/responses":
                key = (arm, hashlib.sha256(payload["instructions"].encode()).hexdigest())
                check(payload["input"], key, index)
                if key in awaiting_adoption:
                    adoptions += 1
                    awaiting_adoption.remove(key)
                prefixes[key] = payload["input"]
            elif path == "/v1/responses/compact":
                key = owners.get((arm, window_fingerprint(payload)))
                if key is None:
                    issues.append({"row": index, "kind": "compact_without_counted_role"})
                else:
                    check(payload["input"], key, index)
        elif path == "/v1/responses" and key is not None:
            prefixes[key] = prefixes[key] + [
                {field: value for field, value in item.items() if field != "status"}
                for item in payload["output"]
            ]
            pending[key] = [
                item["call_id"] for item in payload["output"] if item["type"] == "function_call"
            ]
        elif path == "/v1/responses/compact" and key is not None:
            prefixes[key] = payload["output"]
            pending[key] = []
            awaiting_adoption.add(key)
    return {
        "chain_count": len(prefixes),
        "continuations_checked": continuations,
        "tool_results_checked": tool_results,
        "compaction_adoptions_checked": adoptions,
        "compactions_not_yet_used_by_generation": len(awaiting_adoption),
        "pending_tool_results": sum(map(len, pending.values())),
        "issues": issues,
    }


def retrievals(rows: list[dict[str, Any]]) -> dict[str, Any]:
    calls = {}
    seen = set()
    reads = []
    for row in rows:
        if row.get("path") not in {"/v1/responses", "/v1/responses/compact"}:
            continue
        payload = row["payload"]
        if row["event"] == "response" and row["path"] == "/v1/responses":
            for item in payload["output"]:
                if item["type"] == "function_call":
                    calls[item["call_id"]] = {
                        "name": item["name"],
                        "arguments": item["arguments"],
                        "event_id": row.get("event_id"),
                        "phase": row["phase"],
                    }
        elif row["event"] == "request":
            for item in payload["input"]:
                if item.get("type") != "function_call_output" or item["call_id"] in seen:
                    continue
                seen.add(item["call_id"])
                call = calls.get(item["call_id"])
                if call is None:
                    continue
                content = item["output"]
                reads.append(
                    {
                        **call,
                        "call_id": item["call_id"],
                        "result_utf8_bytes": len(content.encode()),
                        "result_sha256": hashlib.sha256(content.encode()).hexdigest(),
                        "result": content,
                    }
                )
    names = Counter(item["name"] for item in reads)
    repeated = Counter(
        (item["name"], item["result_sha256"]) for item in reads if item["name"].startswith("read_")
    )
    return {
        "completed_tool_results": len(reads),
        "names": dict(names),
        "repeat_read_results": sum(n - 1 for n in repeated.values()),
        "size_unit": "UTF-8 bytes, not provider tokens; exact overall tokens are separate",
        "entries": reads,
    }


def first_turn_contexts(rows: list[dict[str, Any]], scenario: dict[str, Any]) -> list[Any]:
    seen = set()
    observed = []
    for row in rows:
        if (
            row.get("event") != "request"
            or row.get("path") != "/v1/responses"
            or row.get("phase") != "consultant"
            or row["turn"] in seen
        ):
            continue
        seen.add(row["turn"])
        payload = row["payload"]
        items = payload["input"]
        app = json.loads(items[-2]["content"])
        previous_texts = {
            item["content"]
            for item in items[:-2]
            if item.get("role") == "user" and isinstance(item.get("content"), str)
        }
        expected = next(e for e in scenario["events"] if e["event_id"] == row["event_id"])
        early_raw = [
            e["event_id"]
            for e in scenario["events"][: row["turn"] - 1]
            if e["employee_text"] in previous_texts
        ]
        observed.append(
            {
                "event_id": row["event_id"],
                "turn": row["turn"],
                "raw_current_input_unchanged": items[-1]
                == {"role": "user", "content": expected["employee_text"]},
                "app_data_role": items[-2]["role"],
                "app_fields": list(app),
                "recent_sequences": [
                    m["interview_sequence"] for m in app["historical_interview"]["messages"]
                ],
                "interview_read_boundary": app["interview_read_boundary"],
                "prior_employee_inputs_still_plaintext_native": early_raw,
                "scope_note": (
                    "exact standalone user messages only; "
                    "App copies, tool output and opaque states may retain more"
                ),
                "tools": [tool["name"] for tool in payload["tools"]],
            }
        )
    return observed


def analyze(run_dir: Path) -> dict[str, Any]:
    rows = [json.loads(line) for line in (run_dir / "trace.jsonl").read_text("utf-8").splitlines()]
    manifest = json.loads((run_dir / "manifest.json").read_text("utf-8"))
    scenario = json.loads(Path(__file__).with_name("employee-scenario.json").read_text("utf-8"))
    source_issues = []
    for path, value in manifest["sources"].items():
        source = value["source"]
        source_hashes = {
            hashlib.sha256(text.encode()).hexdigest()
            for text in (source, source.replace("\n", "\r\n"))
        }
        if value["sha256"] not in source_hashes:
            source_issues.append({"path": path, "kind": "frozen_copy_mismatch"})
        local = Path(path)
        if local.exists() and hashlib.sha256(local.read_bytes()).hexdigest() != value["sha256"]:
            source_issues.append({"path": path, "kind": "current_source_changed"})
    arms = {}
    pricing = model_profile("gpt-6-luna").pricing
    for arm in ARMS:
        selected = [row for row in rows if row.get("arm") == arm]
        if not selected:
            continue
        costs = []
        for row in selected:
            if row.get("event") != "response":
                continue
            if row["path"] == "/v1/responses":
                costs.append(pricing.estimate_response_cost(restore_response(row["payload"])))
            elif row["path"] == "/v1/responses/compact":
                costs.append(
                    pricing.estimate_compaction_cost(CompactedResponse.construct(**row["payload"]))
                )
        arm_path = run_dir / arm
        arms[arm] = {
            "trace": summarize_trace(selected),
            "native_audit": audit_chains(selected),
            "estimated_generation_and_compaction_usd": str(sum(c for c in costs if c is not None))
            if all(c is not None for c in costs)
            else None,
            "cost_scope": "provider usage estimate, not invoice; counting admin reserve excluded",
            "completed_events": len(list(arm_path.glob("exchange-*.json"))),
            "phase_usage": {
                phase: summarize_trace([r for r in selected if r["phase"] == phase])
                for phase in sorted({r["phase"] for r in selected})
            },
            "retrievals": retrievals(selected),
            "turn_start_contexts": first_turn_contexts(selected, scenario),
        }
    return {
        "status": "offline_observation",
        "source_issues": source_issues,
        "arms": arms,
        "semantic_grading": "manual grading not inferred from keywords or model claims",
    }


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("run_dir", type=Path)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    if args.output.exists():
        parser.error("Do not overwrite prior evidence")
    args.output.write_text(json.dumps(analyze(args.run_dir), ensure_ascii=False, indent=2), "utf-8")

"""Offline pilot evidence only; no model, database or hypothesis-changing operations."""

import argparse
import hashlib
import json
from collections import Counter
from pathlib import Path
from typing import Any

from caliburn.adapters.openai_models import model_profile
from caliburn.adapters.response_serialization import restore_response


def audit_native_chains(rows: list[dict[str, Any]]) -> dict[str, Any]:
    prefixes: dict[tuple[str, str], list[dict[str, Any]]] = {}
    pending_calls: dict[tuple[str, str], list[str]] = {}
    key: tuple[str, str] | None = None
    issues = []
    requests = 0
    continuations = 0
    checked_calls = 0
    for row in rows:
        if row.get("path") != "/v1/responses":
            continue
        payload = row["payload"]
        if row["event"] == "request":
            requests += 1
            key = (row["phase"], payload["instructions"])
            items = payload["input"]
            if key in prefixes:
                continuations += 1
                prefix = prefixes[key]
                if items[: len(prefix)] != prefix:
                    issues.append({"request_index": requests, "kind": "native_prefix_changed"})
                call_ids = [
                    item["call_id"]
                    for item in items[len(prefix) :]
                    if item.get("type") == "function_call_output"
                ]
                if call_ids != pending_calls[key]:
                    issues.append({"request_index": requests, "kind": "tool_call_pairing_changed"})
                checked_calls += len(pending_calls[key])
            prefixes[key] = items
        elif row["event"] == "response":
            if key is None:
                raise ValueError("Generation response without its request")
            output = payload["output"]
            prefixes[key] = prefixes[key] + [
                {field: value for field, value in item.items() if field != "status"}
                for item in output
            ]
            pending_calls[key] = [
                item["call_id"] for item in output if item["type"] == "function_call"
            ]
    return {
        "chain_count": len(prefixes),
        "continuations_checked": continuations,
        "tool_results_checked": checked_calls,
        "pending_tool_results": sum(len(calls) for calls in pending_calls.values()),
        "issues": issues,
    }


def inspect_context(run_dir: Path) -> dict[str, Any]:
    rows = [
        json.loads(line)
        for line in (run_dir / "trace.jsonl").read_text(encoding="utf-8").splitlines()
    ]
    requests = [row for row in rows if row["event"] == "request" and row["path"] == "/v1/responses"]
    turns = []
    for turn in range(1, 6):
        first = next(row for row in requests if row.get("turn") == turn)
        items = first["payload"]["input"]
        reference = json.loads(items[-2]["content"])
        exchange = json.loads((run_dir / f"exchange-{turn}.json").read_text(encoding="utf-8"))
        turns.append(
            {
                "turn": turn,
                "event_id": exchange["event_id"],
                "current_input_unmodified_user_message": items[-1]
                == {"role": "user", "content": exchange["employee_input"]["interview_text"]},
                "app_reference_role": items[-2]["role"],
                "reference_fields": list(reference),
                "memory_map_titles": {
                    layer: [entry["target_title"] for entry in reference[layer]["items"]]
                    for layer in ("work_situation_map", "work_understanding_map")
                },
                "recent_interview_sequences": [
                    message["interview_sequence"]
                    for message in reference["historical_interview"]["messages"]
                ],
                "interview_read_boundary": reference["interview_read_boundary"],
            }
        )
    role_inputs = []
    seen_instructions = set()
    for row in requests:
        payload = row["payload"]
        if row["phase"] != "memory" or payload["instructions"] in seen_instructions:
            continue
        seen_instructions.add(payload["instructions"])
        reference = json.loads(payload["input"][-1]["content"])
        role_inputs.append(
            {
                "instructions_sha256": hashlib.sha256(payload["instructions"].encode()).hexdigest(),
                "app_reference_role": payload["input"][-1]["role"],
                "reference_fields": list(reference),
                "required_interview_range": reference.get("required_interview_range"),
                "historical_interview_sequences": [
                    message["interview_sequence"]
                    for message in reference.get("historical_interview", {}).get("messages", [])
                ],
                "situation_changes": [
                    {"change": change["change"], "target_title": change["target_title"]}
                    for change in reference.get("work_situation_changes", [])
                ],
            }
        )
    return {
        "native_chain_audit": audit_native_chains(rows),
        "store_false_on_all_generations": all(row["payload"]["store"] is False for row in requests),
        "truncation_disabled_on_all_generations": all(
            row["payload"]["truncation"] == "disabled" for row in requests
        ),
        "encrypted_state_requested_on_all_generations": all(
            "reasoning.encrypted_content" in row["payload"]["include"] for row in requests
        ),
        "turn_start_inputs": turns,
        "memory_role_inputs": role_inputs,
    }


def summarize_trace(rows: list[dict[str, Any]]) -> dict[str, Any]:
    requests = [r for r in rows if r["event"] == "request"]
    generations = [r for r in rows if r["event"] == "response" and r.get("path") == "/v1/responses"]
    sent = sum(r.get("path") == "/v1/responses" for r in requests)
    usages = [r["payload"].get("usage") for r in generations]
    missing = sum(not isinstance(usage, dict) for usage in usages)
    valid = [usage for usage in usages if isinstance(usage, dict)]
    tools = Counter(
        item["name"]
        for row in generations
        for item in row["payload"].get("output", [])
        if item["type"] == "function_call"
    )
    return {
        "all_outbound_sends": len(requests),
        "generation_sends": sent,
        "generation_responses": len(generations),
        "unanswered_sends": sent - len(generations),
        "count_sends": sum(r.get("path") == "/v1/responses/input_tokens" for r in requests),
        "compaction_sends": sum(r.get("path") == "/v1/responses/compact" for r in requests),
        "missing_usage_responses": missing,
        "input_tokens": sum(u["input_tokens"] for u in valid) if not missing else None,
        "output_tokens": sum(u["output_tokens"] for u in valid) if not missing else None,
        "cached_input_tokens": sum(u["input_tokens_details"]["cached_tokens"] for u in valid)
        if not missing
        else None,
        "reasoning_tokens": sum(u["output_tokens_details"]["reasoning_tokens"] for u in valid)
        if not missing
        else None,
        "peak_generation_input_tokens": max((u["input_tokens"] for u in valid), default=None),
        "tools": dict(tools),
    }


def executed_script(run_dir: Path, manifest: dict[str, Any]) -> dict[str, Any]:
    """Restore only the two observed review changes, and require the pre-outbound hash.

    This snapshot is reconstructed after start, not claimed to have been frozen earlier.
    No guessed source is saved: a mismatch stops reconstruction.
    """
    key = next(path for path in manifest["sha256"] if path.replace("\\", "/").endswith("/pilot.py"))
    expected = manifest["sha256"][key]
    preserved = run_dir / "executed-script.json"
    if preserved.exists():
        recovered: dict[str, Any] = json.loads(preserved.read_text(encoding="utf-8"))
        if (
            recovered["sha256"] != expected
            or hashlib.sha256(recovered["text"].encode()).hexdigest() != expected
        ):
            raise ValueError("Preserved executed script differs from the pre-outbound manifest")
        return recovered
    source = (Path(__file__).parent / "pilot.py").read_text(encoding="utf-8")
    if hashlib.sha256(source.encode()).hexdigest() != expected:
        start = source.index("\n\ndef validate_database_url(")
        end = source.index('\n\nif __name__ == "__main__":', start)
        source = source[:start] + source[end:]
        source = source.replace(
            "                tokens <= 0\n",
            "                tokens <= 0\n                or tokens >= 128_000\n",
        )
        source = source.replace(
            "    url = validate_database_url(test_database_url())\n",
            """    url = test_database_url()
    info = conninfo_to_dict(url)
    if (
        info.get("host") != "127.0.0.1"
        or info.get("port") != "55441"
        or info.get("dbname") != "caliburn_docker_test"
    ):
        parser.error("Only the fixed isolated research database is allowed")
""",
        )
    actual = hashlib.sha256(source.encode()).hexdigest()
    if actual != expected:
        raise ValueError("Cannot recover the exact executed script; do not substitute current code")
    return {
        "sha256": actual,
        "source_path": key,
        "reconstructed_after_start": True,
        "text": source,
    }


def analyze(run_dir: Path) -> dict[str, Any]:
    rows = [
        json.loads(line)
        for line in (run_dir / "trace.jsonl").read_text(encoding="utf-8").splitlines()
    ]
    result = json.loads((run_dir / "result.json").read_text(encoding="utf-8"))
    manifest = json.loads((run_dir / "manifest.json").read_text(encoding="utf-8"))
    generations = [r for r in rows if r["event"] == "response" and r.get("path") == "/v1/responses"]
    prices = [
        model_profile("gpt-6-luna").pricing.estimate_response_cost(restore_response(row["payload"]))
        for row in generations
    ]
    known_prices = [price for price in prices if price is not None]
    source = executed_script(run_dir, manifest)
    (run_dir / "executed-script.json").write_text(
        json.dumps(source, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    summary = summarize_trace(rows)
    output: dict[str, Any] = {
        **summary,
        "result": result,
        "observed_generation_cost_estimate_usd": str(sum(known_prices))
        if len(known_prices) == len(prices)
        else None,
        "cost_scope": "生成 usage 的本機估算，非帳單；計數服務未有公開計費核對，本批沒有 compact。",
        "by_phase": {
            phase: summarize_trace([r for r in rows if r.get("phase") == phase])
            for phase in sorted({r["phase"] for r in rows if "phase" in r})
        },
        "artifact_sha256": {
            path.name: hashlib.sha256(path.read_bytes()).hexdigest()
            for path in sorted(run_dir.iterdir())
            if path.is_file()
        },
    }
    return output


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("run_dir", type=Path)
    parser.add_argument("--context-only", action="store_true")
    args = parser.parse_args()
    output = args.run_dir / ("context-audit.json" if args.context_only else "analysis.json")
    if output.exists():
        parser.error("Existing analysis must not be overwritten")
    output.write_text(
        json.dumps(
            inspect_context(args.run_dir) if args.context_only else analyze(args.run_dir),
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )
    print("Pilot analysis saved; raw observations unchanged")

"""Bounded continuation: validated completed prefix and cumulative accounting only."""

import hashlib
import json
from decimal import Decimal
from pathlib import Path
from typing import Any

from main_support import StudyAllowance


def validate_prefix(folder: Path) -> dict[str, str]:
    exchanges = sorted(folder.glob("exchange-*.json"))
    products = sorted(folder.glob("product-*.json"))
    expected_exchanges = [
        folder / f"exchange-{index:03d}.json" for index in range(1, 52)
    ]
    expected_products = [folder / f"product-{index:03d}.json" for index in range(1, 52)]
    memories = [folder / f"memory-{event}.json" for event in ("e012", "e028", "e044")]
    if exchanges != expected_exchanges or products != expected_products:
        raise ValueError("Completed prefix must contain exactly events 1 through 51")
    for index, path in enumerate(exchanges, 1):
        if json.loads(path.read_text(encoding="utf-8"))["event_id"] != f"e{index:03d}":
            raise ValueError("Completed prefix has mismatched event identity")
    if not all(path.is_file() for path in memories):
        raise ValueError("Completed prefix is missing a published Memory")
    return {
        path.name: hashlib.sha256(path.read_bytes()).hexdigest()
        for path in [*exchanges, *products, *memories]
    }


class ContinuedAllowance(StudyAllowance):
    """Keep every prior attempted send, including failed e052, in the same US$2 bound."""

    def __init__(self, previous: dict[str, Any]) -> None:
        super().__init__(max_estimated_usd=Decimal("2.00"))
        self.occupied_usd = Decimal(previous["estimated_occupation_usd"]) + Decimal(
            "0.10"
        )
        self.generation_calls = previous["generation_calls"]
        self.compaction_calls = previous["compaction_calls"]
        self.outbound_calls = previous["outbound_calls"]
        self.input_tokens = previous["admitted_input_tokens"]
        if self.occupied_usd >= self.max_estimated_usd:
            raise ValueError("No remaining cumulative study allowance")

"""Research-only source projection and bounded outbound accounting."""

import hashlib
import json
import time
from copy import deepcopy
from decimal import Decimal
from typing import Any

from caliburn.adapters.openai_models import model_profile
from caliburn.adapters.openai_responses import ResponseRequest
